/*
 * Drug catalog import - generated from 'drugs name .xlsx'
 * SAFE to run on production: idempotent, transactional, non-destructive.
 *
 * BEFORE RUNNING: set @TargetUserId below to the pharmacy account (Users.Id)
 * that should own these drugs. The script aborts if it does not exist.
 *
 * Re-running will NOT create duplicates (matched by UserId + Name).
 * Total drug rows extracted: 2748
 */

SET NOCOUNT ON;
SET XACT_ABORT ON;

DECLARE @TargetUserId NVARCHAR(450) = N'PUT-A-VALID-Users.Id-HERE';

IF NOT EXISTS (SELECT 1 FROM dbo.Users WHERE Id = @TargetUserId AND IsDeleted = 0)
BEGIN
    RAISERROR('Aborted: @TargetUserId does not match an existing, non-deleted user.', 16, 1);
    RETURN;
END;

BEGIN TRY
    BEGIN TRAN;

    /* 1) Ensure a fallback category exists for this user (CategoryId is required). */
    DECLARE @CategoryId NVARCHAR(450) =
        (SELECT TOP 1 Id FROM dbo.Categories WHERE UserId = @TargetUserId AND Name = N'Uncategorized' AND IsDeleted = 0);

    IF @CategoryId IS NULL
    BEGIN
        SET @CategoryId = LOWER(CONVERT(NVARCHAR(450), NEWID()));
        INSERT INTO dbo.Categories (Id, Name, Description, IsActive, UserId, CreatedAt, UpdatedAt, IsDeleted)
        VALUES (@CategoryId, N'Uncategorized', N'', 1, @TargetUserId, SYSUTCDATETIME(), NULL, 0);
    END;

    /* 2) Stage the imported rows. */
    CREATE TABLE #Staging (Name NVARCHAR(200), GenericName NVARCHAR(MAX), Packaging NVARCHAR(MAX));

