    /* 3) Insert only drugs that do not already exist for this user (idempotent). */
    ;WITH Src AS (
        SELECT Name, GenericName, Packaging,
               ROW_NUMBER() OVER (PARTITION BY Name ORDER BY (SELECT NULL)) AS rn
        FROM #Staging
    )
    INSERT INTO dbo.Drugs
        (Id, Name, GenericName, Packaging, Barcode, CategoryId, ManufacturerId, Description,
         MinimumStock, Status, IsActive, UserId, CreatedAt, UpdatedAt, IsDeleted)
    SELECT
        LOWER(CONVERT(NVARCHAR(450), NEWID())),
        s.Name,
        ISNULL(s.GenericName, N''),
        ISNULL(s.Packaging, N''),
        N'',                     -- Barcode (unknown)
        @CategoryId,
        NULL,                    -- ManufacturerId (unknown -> NULL)
        N'',                     -- Description (unknown)
        0,                       -- MinimumStock
        3,                       -- Status = OUT_OF_STOCK (no batches yet)
        1,                       -- IsActive
        @TargetUserId,
        SYSUTCDATETIME(),
        NULL,
        0
    FROM Src s
    WHERE s.rn = 1
      AND NOT EXISTS (
        SELECT 1 FROM dbo.Drugs d
        WHERE d.UserId = @TargetUserId AND d.Name = s.Name AND d.IsDeleted = 0
    );

    DECLARE @Inserted INT = @@ROWCOUNT;
    DROP TABLE #Staging;

    COMMIT TRAN;
    PRINT CONCAT('Import complete. Drugs inserted: ', @Inserted);
END TRY
BEGIN CATCH
    IF @@TRANCOUNT > 0 ROLLBACK TRAN;
    THROW;
END CATCH;
